package ru.ilya.lecturerecorder;

import android.app.Activity;
import android.content.Intent;
import android.graphics.Color;
import android.media.MediaPlayer;
import android.os.Bundle;
import android.os.Handler;
import android.view.View;
import android.widget.*;
import java.io.File;
import java.util.Locale;
import org.json.*;

public class LectureReaderActivity extends Activity {
 private final Handler timer=new Handler();private final int fg=Color.rgb(238,242,239);private LinearLayout body,tabs;private TextView heading,status;private ScrollView scroll;private SeekBar position;private Button toggle;private JSONObject document;private File note,edits;private boolean local;private String stamp="",tab="text";private MediaPlayer player;private int pendingSeek=0;private boolean ready=false,foreground=false;
 private int dp(int value){return (int)(getResources().getDisplayMetrics().density*value);}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(fg);t.setPadding(0,dp(9),0,dp(9));return t;}
 private Button button(String value,Runnable action){Button b=new Button(this);b.setText(value);b.setAllCaps(false);b.setOnClickListener(v->action.run());return b;}
 static String clock(double value){long s=Math.max(0,(long)value);return s>=3600?String.format(Locale.US,"%02d:%02d:%02d",s/3600,s/60%60,s%60):String.format(Locale.US,"%02d:%02d",s/60,s%60);}
 @Override public void onCreate(Bundle state){super.onCreate(state);String name=getIntent().getStringExtra("file");if(name==null||!name.matches("lecture-[0-9-]+\\.wav\\.json")){finish();return;}String recording=name.substring(0,name.length()-5);
  local=getIntent().getBooleanExtra("local",false);note=LectureNotes.file(this,recording,local);edits=TranscriptEdits.file(this,recording);
  LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setBackgroundColor(Color.rgb(18,23,25));page.setPadding(dp(16),dp(20),dp(16),dp(12));page.addView(button("← Библиотека",()->finish()));heading=text("Загружаю занятие…",23);page.addView(heading);
  toggle=button("Слушать запись",()->{if(player!=null&&ready&&player.isPlaying()){player.pause();toggle.setText("Продолжить");}else playAt(player!=null&&ready?player.getCurrentPosition():pendingSeek);});page.addView(toggle);status=text("Нажми на фразу в тексте, чтобы услышать её",12);page.addView(status);
  position=new SeekBar(this);position.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int value,boolean user){if(user)playAt(value);}});page.addView(position);
  tabs=new LinearLayout(this);for(String kind:new String[]{"text","summary","review"}){final String key=kind;Button b=button(kind.equals("text")?"Текст":kind.equals("summary")?"Конспект":"Проверить",()->{tab=key;render();});tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));}page.addView(tabs);
  scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(page);refresh();
 }
 private boolean reviewed(JSONObject row){String key=row.optString("review_key");android.content.SharedPreferences prefs=getSharedPreferences("transcript-review",0);return prefs.contains(key)?prefs.getBoolean(key,false):row.optBoolean("reviewed");}
 private void render(){if(document==null)return;int y=scroll.getScrollY();body.removeAllViews();JSONObject report=document.optJSONObject("report");if(report==null)return;heading.setText(report.optString("topic",LectureNotes.title(document)));
  if(tab.equals("summary")){if(report.optBoolean("draft")||report.optBoolean("local_summary_pending")){body.addView(text("Расшифровка готова. Конспект появится после разбора.",16));}else{if(!report.optString("overview").isEmpty())body.addView(text(report.optString("overview"),17));JSONArray points=report.optJSONArray("summary");if(points!=null)for(int i=0;i<points.length();i++)body.addView(text("• "+points.optString(i),16));JSONArray tasks=report.optJSONArray("homework");if(tasks!=null&&tasks.length()>0){body.addView(text("Задания из записи",20));for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);if(task==null)continue;body.addView(text(task.optString("task"),16));final int start=(int)(task.optDouble("start")*1000);body.addView(button("Проверить по записи · "+clock(start/1000.0),()->playAt(start)));}}if(!report.optString("overview").isEmpty()||points!=null&&points.length()>0)body.addView(button("Поделиться конспектом",()->{try{Intent send=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,LectureNotes.summary(document));startActivity(Intent.createChooser(send,"Сохранить или отправить"));}catch(Exception e){status.setText("Не удалось подготовить текст");}}));}}
  else{body.addView(text(tab.equals("review")?"Прослушай сомнительные места и отметь проверенные.":"Таймкоды ведут в исходную аудиозапись.",13));JSONArray rows=report.optJSONArray("segments");int count=0;if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null||tab.equals("review")&&(!row.optBoolean("needs_review")||reviewed(row)))continue;count++;LinearLayout block=new LinearLayout(this);block.setOrientation(1);block.setPadding(dp(10),dp(8),dp(10),dp(12));if(row.optBoolean("needs_review"))block.setBackgroundColor(Color.rgb(48,40,29));final int start=(int)(row.optDouble("start")*1000);boolean timed=row.has("start")&&row.has("end");TextView phrase=text((timed?clock(start/1000.0):"Без таймкода")+"  "+row.optString("text"),17);if(timed)phrase.setOnClickListener(v->playAt(start));phrase.setFocusable(true);phrase.setContentDescription("Слушать с "+clock(start/1000.0)+". "+row.optString("text"));block.addView(phrase);if(row.optBoolean("needs_review")){block.addView(text(reviewed(row)?"Проверено по записи":"Проверь по записи",12));String key=row.optString("review_key");if(!key.isEmpty())block.addView(button(reviewed(row)?"Отменить проверку":"Проверено по записи",()->{getSharedPreferences("transcript-review",0).edit().putBoolean(key,!reviewed(row)).apply();render();}));}String original=row.optString("original_text");if(!original.isEmpty()&&!original.equals(row.optString("text")))block.addView(text("Исходное распознавание: "+original,13));body.addView(block);}if(count==0)body.addView(text(tab.equals("review")?"Непроверенных отметок нет. Это не гарантирует точность остальных фраз.":"Текст ещё готовится на Mac.",16));}
  scroll.post(()->scroll.scrollTo(0,y));
 }
 private void playAt(int millis){pendingSeek=Math.max(0,millis);if(player!=null&&ready){player.seekTo(pendingSeek);player.start();toggle.setText("Пауза");return;}try{String name=document.getString("file");File audio=Store.audio(this,name);if(!audio.isFile()){status.setText("Аудиокопии на телефоне нет. Для новых записей включи сохранение аудио после переноса.");return;}if(player!=null){player.setOnPreparedListener(null);player.release();}player=new MediaPlayer();player.setDataSource(audio.getPath());ready=false;player.setOnPreparedListener(p->{if(p!=player||isFinishing())return;ready=true;position.setMax(p.getDuration());p.seekTo(Math.min(pendingSeek,p.getDuration()));if(foreground){p.start();toggle.setText("Пауза");}});player.setOnCompletionListener(p->{pendingSeek=0;p.seekTo(0);toggle.setText("Слушать сначала");});player.setOnErrorListener((p,w,e)->{ready=false;status.setText("Аудио не открылось. Проверь файл на Mac.");return true;});player.prepareAsync();}catch(Exception e){status.setText("Не удалось включить аудиозапись");}}
 private void refresh(){try{String next=TranscriptEdits.stamp(note)+"/"+TranscriptEdits.stamp(edits);if(!next.equals(stamp)){document=new JSONObject(Store.read(note));try{TranscriptEdits.apply(document,TranscriptEdits.read(edits),local);}catch(Exception ignored){}stamp=next;render();}if(player!=null&&ready){position.setProgress(player.getCurrentPosition());status.setText(clock(player.getCurrentPosition()/1000.0)+" / "+clock(player.getDuration()/1000.0));}}catch(Exception e){status.setText("Текст временно недоступен");}timer.postDelayed(()->refresh(),500);}
 @Override public void onPause(){foreground=false;timer.removeCallbacksAndMessages(null);if(player!=null&&ready)player.pause();super.onPause();}
 @Override public void onResume(){super.onResume();foreground=true;timer.removeCallbacksAndMessages(null);if(note!=null)refresh();}
 @Override public void onDestroy(){timer.removeCallbacksAndMessages(null);if(player!=null){player.setOnPreparedListener(null);player.release();player=null;}super.onDestroy();}
}
